(assert (= "1.12.6" (clojure-version)))
(println "JVM Clojure" (clojure-version))
(def generic-div (fn [x y] (/ x y)))
(def primitive-div (fn [^double x ^double y] (/ x y)))
(let [actual (pr-str (try (generic-div 1.0 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div 1.0 0.0)" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (generic-div -1.0 -0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div -1.0 -0.0)" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (generic-div 0.0 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div 0.0 0.0)" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (generic-div ##NaN 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div ##NaN 0.0)" actual) (assert (= actual "##NaN")))
(let [actual (pr-str (try (generic-div ##Inf -0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div ##Inf -0.0)" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (primitive-div 1.0 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(primitive-div 1.0 0.0)" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (primitive-div -1.0 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(primitive-div -1.0 0.0)" actual) (assert (= actual "##-Inf")))
(let [actual (pr-str (try (primitive-div -1.0 -0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(primitive-div -1.0 -0.0)" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (primitive-div 0.0 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(primitive-div 0.0 0.0)" actual) (assert (= actual "##NaN")))
(let [actual (pr-str (try (primitive-div ##NaN 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(primitive-div ##NaN 0.0)" actual) (assert (= actual "##NaN")))
(let [actual (pr-str (try (/ 1.0 (identity 0.0)) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(/ 1.0 (identity 0.0))" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (/ (identity 1.0) 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(/ (identity 1.0) 0.0)" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (let [x (identity 1.0) y (identity 0.0)] (/ x y)) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(let [x (identity 1.0) y (identity 0.0)] (/ x y))" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (let [x (if true 1.0 2.0) y 0.0] (/ x y)) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(let [x (if true 1.0 2.0) y 0.0] (/ x y))" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (generic-div 1.0 2.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div 1.0 2.0)" actual) (assert (= actual "0.5")))
(let [actual (pr-str (try (primitive-div 1.0 2.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(primitive-div 1.0 2.0)" actual) (assert (= actual "0.5")))
(let [actual (pr-str (try (generic-div -0.0 1.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div -0.0 1.0)" actual) (assert (= actual "-0.0")))
(let [actual (pr-str (try (generic-div ##NaN 1.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div ##NaN 1.0)" actual) (assert (= actual "##NaN")))
(let [actual (pr-str (try (generic-div ##Inf 2.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(generic-div ##Inf 2.0)" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (/ 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(/ 0.0)" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (/ 1.0 0.0 1.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(/ 1.0 0.0 1.0)" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (/ 1.0 2.0 0.0) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(/ 1.0 2.0 0.0)" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (/ 1 (identity 0.0)) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(/ 1 (identity 0.0))" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (let [x 1.0 f (fn [y] (/ x y))] (f 0.0)) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(let [x 1.0 f (fn [y] (/ x y))] (f 0.0))" actual) (assert (= actual "##Inf")))
(let [actual (pr-str (try (let [x (try 1.0) y (try 0.0)] (/ x y)) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(let [x (try 1.0) y (try 0.0)] (/ x y))" actual) (assert (= actual "[:division-error \"Divide by zero\"]")))
(let [actual (pr-str (try (let [events (atom [])] [(try (/ (do (swap! events conj :a) (identity 1.0)) (do (swap! events conj :b) (identity 0.0))) (catch ArithmeticException e :division-error)) @events]) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(let [events (atom [])] [(try (/ (do (swap! events conj :a) (identity 1.0)) (do (swap! events conj :b) (identity 0.0))) (catch :default e :division-error)) @events])" actual) (assert (= actual "[:division-error [:a :b]]")))
(let [actual (pr-str (try (let [events (atom [])] [(try (/ (do (swap! events conj :a) 1) (do (swap! events conj :b) 0) (do (swap! events conj :c) 1.0)) (catch ArithmeticException e :division-error)) @events]) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(let [events (atom [])] [(try (/ (do (swap! events conj :a) 1) (do (swap! events conj :b) 0) (do (swap! events conj :c) 1.0)) (catch :default e :division-error)) @events])" actual) (assert (= actual "[:division-error [:a :b]]")))
(let [actual (pr-str (try (do (def active-div (fn [x y] (/ x y))) (let [old active-div] (def active-div (fn [x y] (/ (double x) y))) [(try (old 1.0 0.0) (catch ArithmeticException e :division-error)) (active-div 1.0 0.0)])) (catch ArithmeticException e [:division-error (ex-message e)])))] (prn "(do (def active-div (fn [x y] (/ x y))) (let [old active-div] (def active-div (fn [x y] (/ (double x) y))) [(try (old 1.0 0.0) (catch :default e :division-error)) (active-div 1.0 0.0)]))" actual) (assert (= actual "[:division-error ##Inf]")))
